int process_file(const char* in_filename, struct Context* ctx) {
    int fd_in = 0;
    int fd_out = 1;
    char out_filename[4096];
    int is_stdin = (in_filename == NULL || strcmp(in_filename, "-") == 0);

    if (!is_stdin) {
        fd_in = open(in_filename, O_RDONLY);
        if (fd_in < 0) {
            fprintf(stderr, "failed to open input file [%s]: %s\n", in_filename, strerror(errno));
            return 1;
        }
    } else {
        in_filename = "standard input";
    }

    if (ctx->test) {
        fd_out = -1;
    } else if (ctx->stdout_flag) {
        fd_out = 1;
    } else if (ctx->output) {
        strncpy(out_filename, ctx->output, sizeof(out_filename)-1);
        int flags = O_WRONLY | O_CREAT | O_TRUNC;
        if (!ctx->force) flags |= O_EXCL;
        fd_out = open(out_filename, flags, 0666);
        if (fd_out < 0) {
            fprintf(stderr, "failed to open output file [%s]: %s\n", out_filename, strerror(errno));
            if (!is_stdin) close(fd_in);
            return 1;
        }
    } else if (!is_stdin) {
        if (ctx->decompress) {
            size_t len = strlen(in_filename);
            size_t slen = strlen(ctx->suffix);
            if (len > slen && strcmp(in_filename + len - slen, ctx->suffix) == 0) {
                strncpy(out_filename, in_filename, len - slen);
                out_filename[len - slen] = '\0';
            } else {
                strncpy(out_filename, in_filename, sizeof(out_filename)-5);
                strcat(out_filename, ".un");
            }
        } else {
            snprintf(out_filename, sizeof(out_filename), "%s%s", in_filename, ctx->suffix);
        }
        int flags = O_WRONLY | O_CREAT | O_TRUNC;
        if (!ctx->force) flags |= O_EXCL;
        fd_out = open(out_filename, flags, 0666);
        if (fd_out < 0) {
            fprintf(stderr, "failed to open output file [%s]: %s\n", out_filename, strerror(errno));
            close(fd_in);
            return 1;
        }
    }

    struct stat statbuf;
    if (!is_stdin && ctx->copy_stat) {
        fstat(fd_in, &statbuf);
    }

    size_t in_size = 0, out_size = 0;
    double t_start = get_time();
    int success = 1;

    #define BUF_SIZE 65536
    uint8_t *in_buf = malloc(BUF_SIZE);
    uint8_t *out_buf = malloc(BUF_SIZE);

    if (ctx->decompress || ctx->test) {
        BrotliDecoderState* s = BrotliDecoderCreateInstance(NULL, NULL, NULL);
        int eof = 0;
        size_t avail_in = 0;
        const uint8_t* next_in = in_buf;
        while (1) {
            if (avail_in == 0 && !eof) {
                ssize_t rd = read(fd_in, in_buf, BUF_SIZE);
                if (rd < 0) { success = 0; break; }
                if (rd == 0) { eof = 1; }
                avail_in = rd;
                next_in = in_buf;
                in_size += rd;
            }

            size_t avail_out = BUF_SIZE;
            uint8_t* next_out = out_buf;

            int res = BrotliDecoderDecompressStream(s, &avail_in, &next_in, &avail_out, &next_out, NULL);
            size_t written = BUF_SIZE - avail_out;
            if (written > 0 && fd_out != -1) {
                if (write(fd_out, out_buf, written) != written) { success = 0; break; }
            }
            out_size += written;

            if (res == 1) { // SUCCESS
                break;
            } else if (res == 0) { // ERROR
                success = 0;
                break;
            } else if (res == 3) { // NEEDS_MORE_OUTPUT
                continue;
            } else if (res == 2) { // NEEDS_MORE_INPUT
                if (eof) { success = 0; break; }
                continue;
            }
        }
        BrotliDecoderDestroyInstance(s);
    } else {
        BrotliEncoderState* s = BrotliEncoderCreateInstance(NULL, NULL, NULL);
        BrotliEncoderSetParameter(s, BROTLI_PARAM_QUALITY, ctx->quality);
        if (ctx->lgwin > 0) BrotliEncoderSetParameter(s, BROTLI_PARAM_LGWIN, ctx->lgwin);
        if (ctx->large_window) BrotliEncoderSetParameter(s, BROTLI_PARAM_LARGE_WINDOW, ctx->large_window);

        int eof = 0;
        size_t avail_in = 0;
        const uint8_t* next_in = in_buf;
        while (1) {
            if (avail_in == 0 && !eof) {
                ssize_t rd = read(fd_in, in_buf, BUF_SIZE);
                if (rd < 0) { success = 0; break; }
                if (rd == 0) { eof = 1; }
                avail_in = rd;
                next_in = in_buf;
                in_size += rd;
            }

            size_t avail_out = BUF_SIZE;
            uint8_t* next_out = out_buf;

            int op = eof ? OP_FINISH : OP_PROCESS;
            int res = BrotliEncoderCompressStream(s, op, &avail_in, &next_in, &avail_out, &next_out, NULL);

            size_t written = BUF_SIZE - avail_out;
            if (written > 0 && fd_out != -1) {
                if (write(fd_out, out_buf, written) != written) { success = 0; break; }
            }
            out_size += written;

            if (eof && avail_in == 0 && avail_out == BUF_SIZE) { // maybe done?
                // actually wait for finish to complete
                // wait, if op is FINISH, res tells us if we are done?
                // actually BrotliEncoderIsFinished is standard, but res==1 for compress does not mean finished, wait, res==0 means error.
                if (res == 0) { success = 0; break; }
                // let's check if finished:
                // actually res is bool. if false(0) -> error. if true(1) -> ok.
                // if we are eof, and written == 0, we are done?
                // let's just use written == 0 as a heuristic.
                if (eof && written == 0) break;
            } else if (res == 0) {
                success = 0; break;
            }
        }
        BrotliEncoderDestroyInstance(s);
    }

    free(in_buf);
    free(out_buf);

    double t_end = get_time();
    double dt = t_end - t_start;

    if (!is_stdin) close(fd_in);
    if (fd_out != 1 && fd_out != -1) close(fd_out);

    if (!success) {
        if (fd_out != 1 && fd_out != -1) unlink(out_filename);
        return 1;
    }

    if (ctx->verbose && fd_out != 1) {
        if (ctx->decompress) {
            printf("Decompressed [%s]: %zu B -> %zu B in %.2f sec\n", is_stdin ? "stdin" : in_filename, in_size, out_size, dt);
        } else {
            printf("Compressed [%s]: %zu B -> %zu B in %.2f sec\n", is_stdin ? "stdin" : in_filename, in_size, out_size, dt);
        }
    }

    if (!is_stdin && ctx->copy_stat && fd_out != 1 && fd_out != -1) {
        chmod(out_filename, statbuf.st_mode);
        chown(out_filename, statbuf.st_uid, statbuf.st_gid);
        struct timespec times[2];
        times[0] = statbuf.st_atim;
        times[1] = statbuf.st_mtim;
        utimensat(AT_FDCWD, out_filename, times, 0);
    }

    if (!is_stdin) {
        if (ctx->rm) {
            unlink(in_filename);
        } else if (ctx->squash && out_size >= in_size) {
            if (fd_out != 1 && fd_out != -1) unlink(out_filename);
        }
    }

    return 0;
}

int main(int argc, char** argv) {
    struct Context ctx;
    memset(&ctx, 0, sizeof(ctx));
    ctx.quality = 11;
    ctx.keep = 1;
    ctx.copy_stat = 1;
    ctx.suffix = ".br";

    if (argv[0]) {
        char *base = basename(argv[0]);
        if (strcmp(base, "unbrotli") == 0) {
            ctx.decompress = 1;
        } else if (strcmp(base, "brcat") == 0) {
            ctx.decompress = 1;
            ctx.concatenated = 1;
            ctx.stdout_flag = 1;
        }
    }

    int opt;
    char options_str[256] = "0123456789cdfjhknso:q:tvw:C:D:KS:VZ";
    while ((opt = getopt_long(argc, argv, options_str, long_options, NULL)) != -1) {
        if (opt >= '0' && opt <= '9') {
            ctx.quality = opt - '0';
        } else if (opt == 'c') {
            ctx.stdout_flag = 1;
        } else if (opt == 'd') {
            ctx.decompress = 1;
        } else if (opt == 'f') {
            ctx.force = 1;
        } else if (opt == 'h') {
            print_help();
            return 0;
        } else if (opt == 'j') {
            ctx.rm = 1;
            ctx.keep = 0;
        } else if (opt == 's') {
            ctx.squash = 1;
        } else if (opt == 'k') {
            ctx.keep = 1;
            ctx.rm = 0;
        } else if (opt == 'n') {
            ctx.copy_stat = 0;
        } else if (opt == 'o') {
            ctx.output = optarg;
        } else if (opt == 'q') {
            ctx.quality = atoi(optarg);
        } else if (opt == 't') {
            ctx.test = 1;
        } else if (opt == 'v') {
            ctx.verbose = 1;
        } else if (opt == 'w') {
            ctx.lgwin = atoi(optarg);
        } else if (opt == 1000) {
            ctx.large_window = atoi(optarg);
        } else if (opt == 'C') {
            // ignore comment for now
        } else if (opt == 'D') {
            // ignore dictionary for now
        } else if (opt == 'K') {
            ctx.concatenated = 1;
        } else if (opt == 'S') {
            ctx.suffix = optarg;
        } else if (opt == 'V') {
            printf("brotli 1.2.0\n");
            return 0;
        } else if (opt == 'Z') {
            ctx.quality = 11;
        } else {
            return 1;
        }
    }

    int file_processed = 0;
    int err = 0;
    for (int i = optind; i < argc; i++) {
        if (process_file(argv[i], &ctx) != 0) err = 1;
        file_processed = 1;
    }

    if (!file_processed) {
        if (process_file(NULL, &ctx) != 0) err = 1;
    }

    return err;
}
